const toneSrc = {};
function engineBg(key) {
  const E = window.BgEngine, st = E.stateFrom(E.PRESETS.find(p => p.name === TONE_BG[key].preset));
  const c = document.createElement('canvas'); c.width = E.W; c.height = E.H;
  c.getContext('2d').drawImage(E.render(st, E.W, E.H), 0, 0);
  return c;
}
function loadToneBgs(done) {
  for (const key of Object.keys(TONE_BG)) {
    if (location.protocol === 'file:') { toneSrc[key] = engineBg(key); continue; }
    const im = new Image();
    im.onload = () => { toneSrc[key] = im; done(key); };
    im.onerror = () => { toneSrc[key] = engineBg(key); done(key); };
    im.src = TONE_BG[key].png;
  }
}

// ---------- shaders (same curl model as pageturn-tool, plus scale / lift / clip for entrances) ----------
